from collections import Counter
from typing import Hashable, List, Sequence, Tuple


def key(z: complex, digits: int = 9) -> Hashable:
    return (round(z.real, digits) + 0.0, round(z.imag, digits) + 0.0)


def sign_with_certificate(alphas: Sequence[complex], s: complex) -> Tuple[int, List[Tuple[complex, complex]]]:
    """Return (sign, pairing certificate) for a duality eigensystem.

    sign = (-1)^{#(-s)}; the certificate lists the dual pairs {a, s^2/a}
    whose products are s^2 and therefore invisible to the sign."""
    bag: Counter = Counter(key(a) for a in alphas)
    lookup = {key(a): a for a in alphas}
    pairs: List[Tuple[complex, complex]] = []
    n_minus = 0
    for k in list(bag):
        a = lookup[k]
        while bag[k] > 0:
            b = s * s / a
            kb = key(b)
            if kb == k:                       # a fixed point: a = +s or a = -s
                bag[k] -= 1
                if kb == key(-s):
                    n_minus += 1
            else:
                if bag[kb] <= 0:
                    raise ValueError("not duality-stable: partner of %s missing" % a)
                bag[k] -= 1; bag[kb] -= 1
                pairs.append((a, b))
    return (-1) ** n_minus, pairs


if __name__ == "__main__":
    import cmath
    s = cmath.sqrt(5)
    beta = 1.3 + 1.7j
    system = [beta, s * s / beta, -s, -s, s, -s]
    eps, cert = sign_with_certificate(system, s)
    prod = 1
    for a in system:
        prod *= a
    print("sign via parity:", eps, " raw product / s^d:", prod / s ** len(system))
    print("certificate pairs:", cert)

from collections import Counter
from typing import Hashable, Sequence, Tuple


def key(z: complex, digits: int = 9) -> Hashable:
    return (round(z.real, digits) + 0.0, round(z.imag, digits) + 0.0)


def invariants(L: Sequence[complex], s: complex) -> Tuple[int, int, Counter]:
    kp, kn = key(s), key(-s)
    n_plus = sum(1 for a in L if key(a) == kp)
    n_minus = sum(1 for a in L if key(a) == kn)
    core = Counter(key(a) for a in L if key(a) not in (kp, kn))
    return n_plus, n_minus, core


def original_moves_equivalent(L: Sequence[complex], M: Sequence[complex], s: complex) -> Tuple[bool, str]:
    """Decide whether L and M are related by permutations, insertion/deletion of
    (-s,-s), and twists alpha -> -alpha in even degree (complete classification)."""
    pL, nL, cL = invariants(L, s)
    pM, nM, cM = invariants(M, s)
    if len(L) % 2 == 1:
        ok = cL == cM and pL == pM and nL % 2 == nM % 2
        return ok, "odd degree: (core, n_+, n_- mod 2) " + ("agree" if ok else "differ")
    neg_cL = Counter({key(-complex(*k)): v for k, v in cL.items()})
    if cL == cM and pL % 2 == pM % 2 and nL % 2 == nM % 2:
        return True, "even degree: same core and same fixed-point parities"
    if cM == neg_cL and pM % 2 == nL % 2 and nM % 2 == pL % 2:
        return True, "even degree: negated core and swapped parities (one twist)"
    return False, "even degree: invariants differ"


