from typing import Dict, Hashable, List, Sequence, Tuple


def key(z: complex, digits: int = 9) -> Hashable:
    return (round(z.real, digits) + 0.0, round(z.imag, digits) + 0.0)


def dual_pair_reduce(L: Sequence[complex], s: complex) -> Tuple[List[complex], List[str]]:
    """Delete dual pairs {b, s^2/b} until one of [], [s,-s], [s], [-s] remains."""
    buckets: Dict[Hashable, List[complex]] = {}
    for a in L:
        buckets.setdefault(key(a), []).append(a)
    log: List[str] = []
    progress = True
    while progress:
        progress = False
        for k in list(buckets):
            while buckets[k]:
                a = buckets[k][-1]
                b = s * s / a
                kb = key(b)
                enough = len(buckets[k]) >= 2 if kb == k else bool(buckets.get(kb))
                if not enough:
                    break
                buckets[k].pop(); buckets[kb].pop()
                log.append(f"delete {{{a:.4g}, {b:.4g}}}")
                progress = True
    return [a for v in buckets.values() for a in v], log


def connect(L: Sequence[complex], M: Sequence[complex], s: complex) -> List[str]:
    """Explicit chain of dual-pair moves from L to M (same degree and sign)."""
    nfL, logL = dual_pair_reduce(L, s)
    nfM, logM = dual_pair_reduce(M, s)
    if sorted(map(key, nfL)) != sorted(map(key, nfM)):
        raise ValueError("different normal forms: degree parity or sign differ")
    return logL + [line.replace("delete", "insert") for line in reversed(logM)]


